    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    rb, cb = [-1] + sep_rows + [h], [-1] + sep_cols + [w]
    row_spans = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_spans = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    # Determine which neighboring panels are a mirrored pair from the stripes
    # where both panels contain a figure. Other stripes complete that pair.
    paired = set()
    for r0, r1 in row_spans:
        occupied = [any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1))
                    for c0, c1 in col_spans]
        for i in range(len(occupied) - 1):
            if occupied[i] and occupied[i + 1]:
                paired.add(i)

    for r0, r1 in row_spans:
        occupied = [any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1))
                    for c0, c1 in col_spans]
        for i in paired:
            if occupied[i] == occupied[i + 1]:
                continue
            src_i, dst_i = (i, i + 1) if occupied[i] else (i + 1, i)
            s0, s1 = col_spans[src_i]
            d0, d1 = col_spans[dst_i]
            width = min(s1 - s0, d1 - d0)
            for r in range(r0, r1):
                for k in range(width):
                    if dst_i > src_i:
                        out[r][d0 + k] = grid[r][s1 - 1 - k]
                    else:
                        out[r][d1 - 1 - k] = grid[r][s0 + k]
    return out
