    rb, cb = [-1] + sep_rows + [h], [-1] + sep_cols + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    # Infer which adjacent panels form a reflection pair, separately for each
    # object color, from bands where both contain matching reflected shapes.
    pairs = set()
    for i in range(len(cols) - 1):
        a0, a1 = cols[i]
        b0, b1 = cols[i + 1]
        if a1 - a0 != b1 - b0:
            continue
        width = a1 - a0
        for r0, r1 in rows:
            for color in range(1, 10):
                left = [[grid[r][a0 + c] == color for c in range(width)] for r in range(r0, r1)]
                right = [[grid[r][b0 + c] == color for c in range(width)] for r in range(r0, r1)]
                if any(any(row) for row in left) and any(any(row) for row in right):
                    if left == [row[::-1] for row in right]:
                        pairs.add((i, color))

    # Complete each learned reflection pair wherever that color appears on
    # only one side of a band.
    for i, color in pairs:
        a0, a1 = cols[i]
        b0, b1 = cols[i + 1]
        width = a1 - a0
        for r0, r1 in rows:
            has_left = any(grid[r][c] == color for r in range(r0, r1) for c in range(a0, a1))
            has_right = any(grid[r][c] == color for r in range(r0, r1) for c in range(b0, b1))
            if has_left == has_right:
                continue
            if has_left:
                for r in range(r0, r1):
                    for c in range(width):
                        if grid[r][a0 + c] == color:
                            out[r][b0 + width - 1 - c] = color
            else:
                for r in range(r0, r1):
                    for c in range(width):
                        if grid[r][b0 + c] == color:
